def find_subsequence_appearing_twice(S):
    n = len(S)
    for length in range(2, n // 2 + 1):
        for i in range(n - length + 1):
            subseq = S[i:i + length]
            first_index = S.find(subseq)
            second_index = S.find(subseq, first_index + 1)
            if second_index != -1:
                return subseq
    return -1

